function option(x:string,locale:NativeLocale):string{
 let m=x.match(/^Article\s+(\d+[A-Z]?)$/);if(m)return (locale==="hi"?"अनुच्छेद ":"ਅਨੁਛੇਦ ")+m[1];
 m=x.match(/^(\d+)(?:st|nd|rd|th) Constitutional Amendment$/);if(m)return m[1]+(locale==="hi"?"वाँ संविधान संशोधन":"ਵੀਂ ਸੰਵਿਧਾਨ ਸੋਧ");
 m=x.match(/^(\d+) years$/);if(m)return m[1]+(locale==="hi"?" वर्ष":" ਸਾਲ");
 if(/^(60|62|65|68)$/.test(x))return x+(locale==="hi"?" वर्ष":" ਸਾਲ");
 const z=O[x];if(z)return z[locale];
 throw new Error("POL-CP-022 missing localized option: "+x);
}
